-- Complete Journey V2.6 administration without changing learner-owned history.
ALTER TABLE public.journey_chapters ADD COLUMN external_id text UNIQUE;
ALTER TABLE public.learning_units ADD COLUMN external_id text UNIQUE;
ALTER TABLE public.lessons ADD COLUMN external_id text UNIQUE;
CREATE TABLE public.journey_lesson_generation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,request_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('processing','pending_review','failed')),cefr_level text NOT NULL,topic text NOT NULL,provider_model text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(created_by,request_id));
ALTER TABLE public.journey_lesson_generation_jobs ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.journey_lesson_generation_jobs FROM anon,authenticated; GRANT ALL ON public.journey_lesson_generation_jobs TO service_role; GRANT SELECT ON public.journey_lesson_generation_jobs TO authenticated; CREATE POLICY journey_generation_admin ON public.journey_lesson_generation_jobs FOR SELECT TO authenticated USING(public.englify_is_admin());
CREATE TABLE public.journey_content_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,lesson_id uuid NOT NULL REFERENCES public.lessons(id) ON DELETE RESTRICT,revision_id uuid NOT NULL REFERENCES public.journey_lesson_revisions(id) ON DELETE RESTRICT,reason text NOT NULL CHECK(reason IN ('incorrect','translation','audio','broken_content','other')),details text NOT NULL DEFAULT '' CHECK(length(details)<=1000),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','dismissed')),resolved_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(reporter_id,revision_id,reason));
ALTER TABLE public.journey_content_reports ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.journey_content_reports FROM anon,authenticated; GRANT ALL ON public.journey_content_reports TO service_role; GRANT INSERT,SELECT ON public.journey_content_reports TO authenticated; CREATE POLICY journey_report_own_insert ON public.journey_content_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='open'); CREATE POLICY journey_report_read ON public.journey_content_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.englify_is_admin());

CREATE FUNCTION public.englify_report_journey_lesson(p_lesson uuid,p_reason text,p_details text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE revision uuid;result public.journey_content_reports; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='28000'; END IF; SELECT r.id INTO revision FROM public.journey_lesson_revisions r JOIN public.lessons l ON l.id=r.lesson_id WHERE l.id=p_lesson AND l.is_published AND l.archived_at IS NULL AND r.status='published'; IF revision IS NULL OR p_reason NOT IN ('incorrect','translation','audio','broken_content','other') OR length(p_details)>1000 THEN RAISE EXCEPTION 'Invalid lesson report' USING ERRCODE='22023'; END IF; INSERT INTO public.journey_content_reports(reporter_id,lesson_id,revision_id,reason,details) VALUES(auth.uid(),p_lesson,revision,p_reason,coalesce(p_details,'')) ON CONFLICT(reporter_id,revision_id,reason) DO UPDATE SET details=excluded.details,status='open',resolved_at=NULL,resolved_by=NULL RETURNING * INTO result; RETURN to_jsonb(result)-'reporter_id'; END $$;
CREATE FUNCTION public.englify_admin_resolve_journey_report(p_id uuid,p_status text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE result public.journey_content_reports; BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF p_status NOT IN ('resolved','dismissed') THEN RAISE EXCEPTION 'Invalid report status' USING ERRCODE='22023'; END IF; UPDATE public.journey_content_reports SET status=p_status,resolved_by=auth.uid(),resolved_at=now() WHERE id=p_id RETURNING * INTO result; IF result.id IS NULL THEN RAISE SQLSTATE 'PT404' USING MESSAGE='Report not found'; END IF; INSERT INTO public.admin_audit_logs(actor_id,action,resource,record_id,after_data) VALUES(auth.uid(),'resolve:'||p_status,'journey-content-report',result.id,to_jsonb(result)-'reporter_id'); RETURN to_jsonb(result)-'reporter_id'; END $$;
ALTER FUNCTION public.englify_admin_journey_overview() RENAME TO englify_admin_journey_overview_v1;
CREATE FUNCTION public.englify_admin_journey_overview() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.englify_admin_journey_overview_v1()||jsonb_build_object('reported_content',(SELECT count(*) FROM public.journey_content_reports WHERE status='open'),'reports',(SELECT coalesce(jsonb_agg(to_jsonb(r)-'reporter_id' ORDER BY created_at DESC),'[]') FROM (SELECT * FROM public.journey_content_reports WHERE status='open' ORDER BY created_at DESC LIMIT 30)r)) $$;

CREATE FUNCTION public.englify_admin_save_journey_node(p_kind text,p_id uuid,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF;
 IF p_kind='chapter' THEN INSERT INTO public.journey_chapters(id,course_id,slug,title,description,learning_objectives,position,curriculum_version,lifecycle_status,is_published)
 VALUES(coalesce(p_id,gen_random_uuid()),(p_data->>'course_id')::uuid,p_data->>'slug',p_data->>'title',coalesce(p_data->>'description',''),coalesce(p_data->'learning_objectives','[]'),(p_data->>'position')::int,coalesce((p_data->>'curriculum_version')::int,1),'draft',false)
 ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,learning_objectives=excluded.learning_objectives,position=excluded.position,updated_at=now() WHERE journey_chapters.lifecycle_status<>'published' RETURNING to_jsonb(journey_chapters.*) INTO result;
 ELSIF p_kind='unit' THEN INSERT INTO public.learning_units(id,course_id,chapter_id,slug,title,description,learning_objectives,position,estimated_minutes,is_required,lifecycle_status,is_published)
 VALUES(coalesce(p_id,gen_random_uuid()),(p_data->>'course_id')::uuid,(p_data->>'chapter_id')::uuid,p_data->>'slug',p_data->>'title',coalesce(p_data->>'description',''),coalesce(p_data->'learning_objectives','[]'),(p_data->>'position')::int,coalesce((p_data->>'estimated_minutes')::int,60),coalesce((p_data->>'is_required')::boolean,true),'draft',false)
 ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,learning_objectives=excluded.learning_objectives,position=excluded.position,estimated_minutes=excluded.estimated_minutes,is_required=excluded.is_required WHERE learning_units.lifecycle_status<>'published' RETURNING to_jsonb(learning_units.*) INTO result;
 ELSE RAISE EXCEPTION 'Unsupported curriculum node' USING ERRCODE='22023'; END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'Published nodes require a new curriculum version' USING ERRCODE='PT409'; END IF;
 INSERT INTO public.admin_audit_logs(actor_id,action,resource,record_id,after_data) VALUES(auth.uid(),CASE WHEN p_id IS NULL THEN 'create' ELSE 'update' END,'journey-'||p_kind,(result->>'id')::uuid,result); RETURN result; END $$;

CREATE FUNCTION public.englify_admin_reorder_journey(p_kind text,p_parent uuid,p_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE node_id uuid; pos int:=0; affected int;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF cardinality(p_ids)=0 OR cardinality(p_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(p_ids))) THEN RAISE EXCEPTION 'Invalid ordering' USING ERRCODE='22023'; END IF;
 FOREACH node_id IN ARRAY p_ids LOOP pos:=pos+1; IF p_kind='chapter' THEN UPDATE public.journey_chapters c SET position=100000+pos WHERE c.id=node_id AND c.course_id=p_parent AND c.lifecycle_status<>'published'; ELSIF p_kind='unit' THEN UPDATE public.learning_units u SET position=100000+pos WHERE u.id=node_id AND u.chapter_id=p_parent AND u.lifecycle_status<>'published'; ELSIF p_kind='lesson' THEN UPDATE public.lessons l SET position=100000+pos WHERE l.id=node_id AND l.unit_id=p_parent AND l.lifecycle_status<>'published'; ELSE RAISE EXCEPTION 'Invalid ordering kind' USING ERRCODE='22023'; END IF; GET DIAGNOSTICS affected=ROW_COUNT; IF affected<>1 THEN RAISE EXCEPTION 'Only complete draft siblings may be reordered' USING ERRCODE='PT409'; END IF; END LOOP;
 pos:=0; FOREACH node_id IN ARRAY p_ids LOOP pos:=pos+1; IF p_kind='chapter' THEN UPDATE public.journey_chapters c SET position=pos WHERE c.id=node_id; ELSIF p_kind='unit' THEN UPDATE public.learning_units u SET position=pos WHERE u.id=node_id; ELSE UPDATE public.lessons l SET position=pos WHERE l.id=node_id; END IF; END LOOP; RETURN jsonb_build_object('reordered',cardinality(p_ids)); END $$;

CREATE FUNCTION public.englify_admin_save_journey_checkpoint(p_lesson uuid,p_unit uuid,p_objectives jsonb,p_passing smallint DEFAULT 70) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result public.journey_checkpoint_configs;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF p_passing<>70 OR jsonb_typeof(p_objectives)<>'array' OR jsonb_array_length(p_objectives)=0 OR NOT EXISTS(SELECT 1 FROM public.lessons WHERE id=p_lesson AND unit_id=p_unit AND lesson_kind='checkpoint') THEN RAISE EXCEPTION 'Invalid checkpoint configuration' USING ERRCODE='22023'; END IF;
 INSERT INTO public.journey_checkpoint_configs(lesson_id,unit_id,passing_percent,objectives,is_published) VALUES(p_lesson,p_unit,p_passing,p_objectives,false) ON CONFLICT(lesson_id) DO UPDATE SET objectives=excluded.objectives,updated_at=now() WHERE NOT journey_checkpoint_configs.is_published RETURNING * INTO result; IF result.lesson_id IS NULL THEN RAISE EXCEPTION 'Published checkpoints are immutable' USING ERRCODE='PT409'; END IF; RETURN to_jsonb(result); END $$;

CREATE FUNCTION public.englify_admin_stage_journey_import(p_request_id uuid,p_filename text,p_format text,p_rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE batch public.journey_import_batches; row record; errors jsonb; valid int:=0;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF p_request_id IS NULL OR p_format NOT IN ('csv','xlsx') OR jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 OR length(p_filename)>180 THEN RAISE EXCEPTION 'Invalid import batch' USING ERRCODE='22023'; END IF;
 SELECT * INTO batch FROM public.journey_import_batches WHERE created_by=auth.uid() AND request_id=p_request_id; IF FOUND THEN RETURN jsonb_build_object('batch_id',batch.id,'replayed',true); END IF;
 INSERT INTO public.journey_import_batches(created_by,request_id,filename,format,row_count) VALUES(auth.uid(),p_request_id,p_filename,p_format,jsonb_array_length(p_rows)) RETURNING * INTO batch;
 FOR row IN SELECT value,ordinality FROM jsonb_array_elements(p_rows) WITH ORDINALITY LOOP errors:='[]'; IF row.value->>'entity' NOT IN ('chapter','unit','lesson','block') OR coalesce(row.value->>'external_id','') !~ '^[A-Za-z0-9_-]{1,80}$' OR length(btrim(coalesce(row.value->>'title',''))) = 0 THEN errors:=errors||jsonb_build_array('invalid required fields'); END IF; IF EXISTS(SELECT 1 FROM public.journey_import_rows r WHERE r.batch_id=batch.id AND r.raw_data->>'external_id'=row.value->>'external_id') OR EXISTS(SELECT 1 FROM public.lessons WHERE external_id=row.value->>'external_id') OR EXISTS(SELECT 1 FROM public.learning_units WHERE external_id=row.value->>'external_id') OR EXISTS(SELECT 1 FROM public.journey_chapters WHERE external_id=row.value->>'external_id') THEN errors:=errors||jsonb_build_array('duplicate external_id'); END IF; IF jsonb_array_length(errors)=0 THEN valid:=valid+1; END IF; INSERT INTO public.journey_import_rows(batch_id,row_number,raw_data,validation_errors) VALUES(batch.id,row.ordinality+1,row.value,errors); END LOOP;
 RETURN jsonb_build_object('batch_id',batch.id,'row_count',batch.row_count,'valid_count',valid,'rows',(SELECT jsonb_agg(to_jsonb(r) ORDER BY row_number) FROM public.journey_import_rows r WHERE batch_id=batch.id)); END $$;

CREATE FUNCTION public.englify_admin_commit_journey_import(p_batch uuid,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE batch public.journey_import_batches; row public.journey_import_rows; data jsonb; new_id uuid; imported int:=0;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; SELECT b.* INTO batch FROM public.journey_import_batches b WHERE b.id=p_batch AND b.created_by=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE SQLSTATE 'PT404' USING MESSAGE='Import batch not found'; END IF; IF batch.status='committed' THEN RETURN jsonb_build_object('batch_id',batch.id,'imported',(SELECT count(*) FROM public.journey_import_rows WHERE batch_id=batch.id AND imported_id IS NOT NULL),'replayed',true); END IF;
 FOR row IN SELECT * FROM public.journey_import_rows WHERE batch_id=batch.id AND jsonb_array_length(validation_errors)=0 ORDER BY CASE raw_data->>'entity' WHEN 'chapter' THEN 1 WHEN 'unit' THEN 2 WHEN 'lesson' THEN 3 ELSE 4 END,row_number LOOP data:=row.raw_data;
  IF data->>'entity'='chapter' THEN INSERT INTO public.journey_chapters(course_id,slug,title,description,position,external_id,lifecycle_status) VALUES((data->>'course_id')::uuid,data->>'slug',data->>'title',coalesce(data->>'description',''),(data->>'position')::int,data->>'external_id','draft') RETURNING id INTO new_id;
  ELSIF data->>'entity'='unit' THEN INSERT INTO public.learning_units(course_id,chapter_id,slug,title,position,external_id,lifecycle_status) SELECT (data->>'course_id')::uuid,c.id,data->>'slug',data->>'title',(data->>'position')::int,data->>'external_id','draft' FROM public.journey_chapters c WHERE c.external_id=data->>'parent_external_id' RETURNING learning_units.id INTO new_id;
  ELSIF data->>'entity'='lesson' THEN INSERT INTO public.lessons(course_id,unit_id,slug,title,objective,position,external_id,lifecycle_status) SELECT (data->>'course_id')::uuid,u.id,data->>'slug',data->>'title',coalesce(data->>'objective',''),(data->>'position')::int,data->>'external_id','draft' FROM public.learning_units u WHERE u.external_id=data->>'parent_external_id' RETURNING lessons.id INTO new_id;
  ELSE CONTINUE; END IF; IF new_id IS NULL THEN RAISE EXCEPTION 'Missing import parent for row %',row.row_number USING ERRCODE='22023'; END IF; UPDATE public.journey_import_rows SET imported_id=new_id WHERE journey_import_rows.id=row.id; imported:=imported+1; new_id:=NULL; END LOOP;
 UPDATE public.journey_import_batches SET status='committed',committed_at=now() WHERE journey_import_batches.id=batch.id; RETURN jsonb_build_object('batch_id',batch.id,'imported',imported); END $$;

CREATE FUNCTION public.englify_admin_journey_analytics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('lesson_starts',(SELECT count(*) FROM public.learning_progress WHERE status<>'locked'),'lesson_completions',(SELECT count(*) FROM public.learning_progress WHERE status IN ('completed','mastered')),'attempts',(SELECT count(*) FROM public.lesson_attempts),'average_score',(SELECT round(avg(correct_count*100.0/greatest(question_count,1)),1) FROM public.lesson_attempts),'checkpoint_pass_rate',(SELECT round(count(*) FILTER(WHERE passed)*100.0/nullif(count(*),0),1) FROM public.journey_checkpoint_attempts),'version_usage',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM (SELECT revision_id,count(*) attempts FROM public.lesson_attempts WHERE revision_id IS NOT NULL GROUP BY revision_id ORDER BY count(*) DESC LIMIT 20)x)); END $$;

REVOKE ALL ON FUNCTION public.englify_admin_save_journey_node(text,uuid,jsonb),public.englify_admin_reorder_journey(text,uuid,uuid[]),public.englify_admin_save_journey_checkpoint(uuid,uuid,jsonb,smallint),public.englify_admin_stage_journey_import(uuid,text,text,jsonb),public.englify_admin_commit_journey_import(uuid,uuid),public.englify_admin_journey_analytics(),public.englify_report_journey_lesson(uuid,text,text),public.englify_admin_resolve_journey_report(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.englify_admin_save_journey_node(text,uuid,jsonb),public.englify_admin_reorder_journey(text,uuid,uuid[]),public.englify_admin_save_journey_checkpoint(uuid,uuid,jsonb,smallint),public.englify_admin_stage_journey_import(uuid,text,text,jsonb),public.englify_admin_commit_journey_import(uuid,uuid),public.englify_admin_journey_analytics(),public.englify_report_journey_lesson(uuid,text,text),public.englify_admin_resolve_journey_report(uuid,text) TO authenticated;
REVOKE ALL ON FUNCTION public.englify_admin_journey_overview(),public.englify_admin_journey_overview_v1() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.englify_admin_journey_overview() TO authenticated;
